<style>
.tms-quiz-strip {
    width: 100%;
    background: linear-gradient(135deg, #4a5568 0%, #2d3748 50%, #1a202c 100%);
    padding: 15px 0px;
    position: relative;
    overflow: hidden;
    margin: 0;
    box-sizing: border-box;
}

.tms-quiz-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    position: relative;
}

.tms-quiz-link {
    display: block;
    text-decoration: none;
    color: white;
    transition: all 0.3s ease;
}

.tms-quiz-link:hover {
    color: #e2e8f0;
    text-decoration: none;
}

.tms-quiz-content {
    text-align: center;
    position: relative;
}

.tms-quiz-text {
    font-size: 18px !important;
    font-weight: 600 !important;
    color: white !important;
    margin: 0;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    transition: all 0.3s ease;
}

.tms-quiz-link:hover .tms-quiz-text {
    transform: translateY(-2px);
    text-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
}

.tms-quiz-arrow {
    display: inline-block;
    margin-left: 10px;
    font-size: 20px;
    transition: transform 0.3s ease;
}

.tms-quiz-link:hover .tms-quiz-arrow {
    transform: translateX(5px);
}

/* Responsive Design */
@media (max-width: 768px) {
    .tms-quiz-strip {
        padding: 15px 0;
    }
    
    .tms-quiz-container {
        padding: 0 15px;
    }
    
    .tms-quiz-text {
        font-size: 16px;
    }
    
    .tms-quiz-strip::before {
        width: 200px;
    }
    
    .tms-quiz-strip::after {
        width: 100px;
    }
}

@media (max-width: 480px) {
    .tms-quiz-text {
        font-size: 14px;
        line-height: 1.4;
    }
    
    .tms-quiz-strip::before {
        width: 150px;
    }
    
    .tms-quiz-strip::after {
        width: 75px;
    }
}

/* WordPress compatibility */
.tms-quiz-strip * {
    box-sizing: border-box;
}

/* Ensure full width in WordPress */
.tms-quiz-strip {
    margin-left: calc(-50vw + 50%);
    margin-right: calc(-50vw + 50%);
    width: 99.5vw;
    position: relative;
}

/* Animation for engagement */
@keyframes pulse {
    0% { opacity: 1; }
    50% { opacity: 0.8; }
    100% { opacity: 1; }
}

.tms-quiz-link:hover::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 255, 255, 0.1);
    animation: pulse 2s infinite;
    border-radius: 4px;
}
	
	
	@media (max-width: 1023px) {
    .page-id-69 .top-section .section-content {
        display: none !important;
    }
}
	
	@media screen and (min-width:1023px){

   .tms-quiz-strip{
       margin-top:30px !important;     
    }

}
	
</style>
